pub const Case = struct { shape: usize, seed: u64, position: u64, temperature: f64, top_k: usize, top_p: f64, min_p: f64, want: i64 };
pub const Sum = struct { n: usize, bits: u64 };
pub const Ceil = struct { p: f64, n: u64, want: u64 };

